  }

  let ignoredCopies = 0;
  const result: OwnedCard[] = [];
  for (const entry of byCard.values()) {
    const allowed = Math.min(entry.quantity, singletonLimit(entry.row));
    ignoredCopies += entry.quantity - allowed;
    result.push({ row: entry.row, quantity: allowed });
