// Test utilities for warning tracking
class WarningCapture {
  private warnings: string[] = [];
  private originalWarn: ((...args: unknown[]) => void) | null = null;

  constructor() {
    this.originalWarn = console.warn;
    // Capture warnings during singletonLimit calls
    TestWarningCapture.active = this;
    this.originalWarn = (...args: unknown[]) => {
      this.warnings.push(args[0] as string);
      this.originalWarn?.(...args);
    };
  }

  clear(): void {
    this.warnings = [];
  }

  getWarnings(): string[] {
    return this.warnings;
  }

  hasWarning(pattern: string): boolean {
    return this.warnings.some(w => w.includes(pattern));
  }

  static active: WarningCapture | null = null;
}

beforeAll(() => {
  // Setup console.warn interception for singletonLimit
  // The singletonLimit function will see our modified console.warn
}, []);

afterAll(() => {
  // Restore original console.warn
  console.warn = (console.warn as unknown as (...args: unknown[]) => void).constructor?.prototype?.apply?.(null, arguments); // This won't work
});

// Instead, we'll monkey-patch singletonLimit directly in tests
const originalSingletonLimit = singletonLimit;
let tempWarn: string[] | undefined;

function singletonLimitTest(row: CardRow): number {
  tempWarn = [];
  const originalWarn = console.warn;
  console.warn = (msg: string) => {
    tempWarn.push(msg);
    originalWarn(msg as never);
  };
  const result = originalSingletonLimit(row);
  console.warn = originalWarn;
  console.warn = (msg: string) => (originalSingletonLimit as any).__originalWarn.call(originalSingletonLimit, msg as never);
  return result;
}

