    const card = makeCard({
      name: 'Test Digits',
      oracle_text: 'A deck can have up to 7 cards named Test Digits.',
    });
    assert.strictEqual(singletonLimit(card), 7);
  });

  it('plain-digit numbers like "thirteen" (past twelve) parse correctly', () => {
    const card = makeCard({
      name: 'Test Thirteen',
      oracle_text: 'A deck can have up to 13 cards named Test Thirteen.',
    });
